using System;
using System.IO;
using System.Linq;
using CircuitoStudio;
class ProjectEditingTests {
 static int n;static void Check(bool b,string message){n++;if(!b)throw new Exception(message);}
 static void Reject(Action action){try{action();}catch(InvalidOperationException){n++;return;}catch(InvalidDataException){n++;return;}throw new Exception("Invalid edit accepted");}
 static Project Network(){var p=new Project();var a=new Board{Id="A",Name="Raiz",Voltage=380};var b=new Board{Id="B",Name="Intermediário",Voltage=380};var c=new Board{Id="C",Name="Final",Voltage=380};a.Circuits.Add(new Circuit{Id="TA",PowerKw=2,Voltage=220});a.Circuits.Add(new Circuit{Id="AB",PowerKw=999,Voltage=380,Phases=PhaseMode.Trifasico,PhaseLabel="ABC",ChildBoardId="B"});b.Circuits.Add(new Circuit{Id="TB",PowerKw=4,Voltage=220});b.Circuits.Add(new Circuit{Id="BC",PowerKw=888,Voltage=380,Phases=PhaseMode.Trifasico,PhaseLabel="ABC",ChildBoardId="C"});c.Circuits.Add(new Circuit{Id="TC",PowerKw=3,Voltage=220});p.Boards.AddRange(new[]{a,b,c});p.Validate();return p;}
 static void Main(){string dir=Path.Combine(Path.GetTempPath(),"editing-tests-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);try{
  var p=new Project();p.Source.LineVoltage=400;var root=new Board{Id="C1",Name="Raiz",Voltage=400};var original=new Circuit{Id="Q1",Name="Carga Ω",PowerKw=1,Voltage=230,DiagramLabel="Etiqueta Ç",DrawingSymbol=DiagramSymbol.Motor,DiagramX=500,DinRow=2,DinColumn=3,DinModules=4,PhaseLocked=true};original.Cable.AmpacityA=50;root.Circuits.Add(original);p.Boards.Add(root);var added=ProjectEditing.AddBoard(p);Check(added.Id=="Q2"&&added.Voltage==400,"Board IDs consider circuit IDs and use source voltage");var feeder=ProjectEditing.AddCircuit(p,root);Check(feeder.Id=="C2"&&Math.Abs(feeder.Voltage-230.9)<1e-9,"Circuit IDs consider board IDs and derive phase-neutral voltage");feeder.ChildBoardId=added.Id;feeder.Phases=PhaseMode.Trifasico;feeder.Voltage=400;feeder.PhaseLabel="ABC";p.Validate();ProjectEditing.RenameBoard(p,added,"Distribuição 北");ProjectEditing.RenameCircuit(p,root,feeder,"Alimentador Ç");Check(feeder.ChildBoardId==added.Id&&added.Name=="Distribuição 北"&&feeder.Name=="Alimentador Ç","Renames preserve topology and Unicode");Reject(delegate{ProjectEditing.DuplicateCircuit(p,root,feeder);});Check(root.Circuits.Count==2,"Refused feeder duplicate leaves graph intact");
  var duplicate=ProjectEditing.DuplicateCircuit(p,root,original);Check(duplicate.Id=="C3"&&duplicate.DiagramLabel=="Etiqueta Ç"&&duplicate.DrawingSymbol==DiagramSymbol.Motor,"Duplicate gets unique ID and preserves appearance");Check(!Object.ReferenceEquals(original.Cable,duplicate.Cable)&&duplicate.Cable.AmpacityA==50,"Duplicate deeply copies technical data");Check(duplicate.DiagramX==0&&duplicate.DinRow==0&&duplicate.DinColumn==0&&duplicate.DinModules==4&&duplicate.PhaseLocked,"Duplicate clears placements and preserves constraints");ProjectEditing.RemoveCircuit(p,root,duplicate);Check(root.Circuits.Count==2&&!root.Circuits.Contains(duplicate),"Remove terminal circuit");string name=added.Name;Reject(delegate{ProjectEditing.RenameBoard(p,added,"");});Check(added.Name==name,"Invalid rename leaves old name intact");Reject(delegate{ProjectEditing.AddCircuit(p,new Board());});Reject(delegate{ProjectEditing.RemoveBoard(p,new Board());});Check(p.Boards.Count==2,"Foreign edits leave graph intact");
  p=Network();Check(Engineering.Analyze(p).TotalKw==9,"Initial three-level network aggregates without feeder placeholders");var a=p.Boards[0];var middle=p.Boards[1];var final=p.Boards[2];var terminal=final.Circuits[0];int removed=ProjectEditing.RemoveBoard(p,middle);p.Validate();Check(removed==1&&p.Boards.Count==2&&!a.Circuits.Any(c=>c.ChildBoardId=="B"),"Removing board removes its incoming feeder without dangling reference");Check(p.Boards.Contains(final)&&Object.ReferenceEquals(final.Circuits[0],terminal),"Downstream board remains intact as independent root");Check(Engineering.Analyze(p).TotalKw==5,"Removed feeder cannot become phantom 999 kW load");string saved=Path.Combine(dir,"network.circuito");p.Save(saved);Check(Engineering.Analyze(Project.Load(saved)).TotalKw==5,"Edited graph survives save/reopen");
  p=Network();a=p.Boards[0];ProjectEditing.RemoveCircuit(p,a,a.Circuits.Single(c=>c.ChildBoardId=="B"));p.Validate();Check(p.Boards.Count==3&&Engineering.Analyze(p).TotalKw==9,"Removing feeder preserves downstream subtree as independent root");Console.WriteLine("PASS: "+n+" project editing assertions");
 }finally{Directory.Delete(dir,true);}}
}
